/// Owns the pinned managed array backing a <see cref="SliceMutUint"/> view.
public sealed class SliceMutUintLease : IDisposable
{
    private GCHandle _handle;
    private readonly SliceMutUint.Lifetime _lifetime;

    internal SliceMutUintLease(uint[] managed)
    {
        _handle = GCHandle.Alloc(managed, GCHandleType.Pinned);
        _lifetime = new SliceMutUint.Lifetime(this);
        Slice = new SliceMutUint(_handle.AddrOfPinnedObject(), (ulong)managed.Length, _lifetime, managed);
    }

    /// The borrowed slice backed by this lease.
    public SliceMutUint Slice { get; }

    /// Returns the borrowed slice backed by this lease.
    public static implicit operator SliceMutUint(SliceMutUintLease lease)
    {
        ArgumentNullException.ThrowIfNull(lease);
        return lease.Slice;
    }

    /// Unpins the managed array and invalidates the borrowed slice.
    public void Dispose()
    {
        _lifetime.Invalidate();
        if (_handle is { IsAllocated: true }) { _handle.Free(); }
        GC.SuppressFinalize(this);
    }

    ~SliceMutUintLease()
    {
        _lifetime.Invalidate();
        if (_handle is { IsAllocated: true }) { _handle.Free(); }
    }
}

/// Convenience extension to pin a <c>uint[]</c> array for use as a slice.
public static class SliceMutUintExtensions
{
    /// Pins the array until the returned lease is disposed.
    public static SliceMutUintLease SliceMut(this uint[] s) { return SliceMutUint.From(s); }
}


